static void pump(double s){NSDate*e=[NSDate dateWithTimeIntervalSinceNow:s];while(e.timeIntervalSinceNow>0){NSEvent*n=[NSApp nextEventMatchingMask:NSEventMaskAny untilDate:[NSDate dateWithTimeIntervalSinceNow:.02] inMode:NSDefaultRunLoopMode dequeue:YES];if(n)[NSApp sendEvent:n];}}
static void key(id o,NSString*k){@try{id v=[o valueForKey:k];printf("  %s = %s\n",k.UTF8String,v?[[NSString stringWithFormat:@"<%@> %@",[v class],v] UTF8String]:"<nil>");}@catch(NSException*e){printf("  %s = <exception: %s>\n",k.UTF8String,e.reason.UTF8String);}}
static void matrix(id f){@try{id v=[f valueForKey:@"inputColorMatrix"];if([v isKindOfClass:[NSValue class]]){NSUInteger n=0,a=0;const char*t=[v objCType];NSGetSizeAndAlignment(t,&n,&a);printf("MATRIX_TYPE %s size=%lu\n",t,(unsigned long)n);if(n==80){unsigned char bytes[80];[v getValue:bytes size:80];printf("MATRIX_HEX ");for(int i=0;i<80;i++)printf("%02x",bytes[i]);puts("");}}}@catch(NSException*e){printf("MATRIX_EXCEPTION %s\n",e.reason.UTF8String);}}
static void walk(CALayer*l,int d){if(!l||d>18)return;NSString*c=NSStringFromClass(l.class);printf("LAYER depth=%d class=%s frame=%s opacity=%g\n",d,c.UTF8String,NSStringFromRect(NSRectFromCGRect(l.frame)).UTF8String,l.opacity);if([c containsString:@"Backdrop"]||[c containsString:@"SDF"]){for(NSString*k in @[@"scale",@"backdropRect",@"marginWidth",@"effect",@"effectOffset",@"mode",@"operation",@"cornerRadius"])key(l,k);id e=nil;@try{e=[l valueForKey:@"effect"];}@catch(NSException*x){}if(e){printf("EFFECT class=%s\n",NSStringFromClass([e class]).UTF8String);for(NSString*k in @[@"keyColor",@"fillColor",@"keyHeight",@"fillHeight",@"keyAngle",@"fillAngle",@"keySpread",@"fillSpread",@"keyAmount",@"fillAmount",@"keyHeightScale",@"keyHeightOffset",@"fillHeightScale",@"fillHeightOffset",@"keySpreadScale",@"keySpreadOffset",@"fillSpreadScale",@"fillSpreadOffset",@"global",@"curvature"])key(e,k);}}for(id f in l.filters){NSString*n=nil;@try{n=[f valueForKey:@"name"];}@catch(NSException*e){}printf("FILTER name=%s\n",n.UTF8String?:"<nil>");if([n isEqualToString:@"glassBackground"]){@try{NSArray*ks=[f valueForKey:@"inputKeys"];printf("INPUT_COUNT %lu\n",(unsigned long)ks.count);for(NSString*k in ks)key(f,k);}@catch(NSException*e){printf("INPUT_KEYS_EXCEPTION %s\n",e.reason.UTF8String);}}if([n isEqualToString:@"vibrantColorMatrix"]){for(NSString*k in @[@"inputBackdropAware",@"inputClamp",@"inputClampPreserveHue",@"enabled"])key(f,k);matrix(f);}}for(CALayer*s in l.sublayers)walk(s,d+1);}
