int main(int argc,const char**argv){@autoreleasepool{if(argc<2)return 3;id<MTLDevice>dev=MTLCreateSystemDefaultDevice();printf("OS %s\nMETAL device=%s\n",NSProcessInfo.processInfo.operatingSystemVersionString.UTF8String,dev?dev.name.UTF8String:"<nil>");[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];[NSApp finishLaunching];NSWindow*w=[[NSWindow alloc]initWithContentRect:NSMakeRect(100,100,800,500) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];GlassProbePatternView*r=[[GlassProbePatternView alloc]initWithFrame:NSMakeRect(0,0,800,500)];r.wantsLayer=YES;w.contentView=r;Class G=NSClassFromString(@"NSGlassEffectView"),C=NSClassFromString(@"NSGlassEffectContainerView");if(!G)return 2;NSView*b=C?[[C alloc]initWithFrame:r.bounds]:r;if(b!=r)[r addSubview:b];NSView*g=[[G alloc]initWithFrame:NSMakeRect(100,225,600,44)];@try{[g setValue:@22 forKey:@"cornerRadius"];}@catch(NSException*e){printf("RADIUS_EXCEPTION %s\n",e.reason.UTF8String);}[b addSubview:g];[NSApp activateIgnoringOtherApps:YES];[w makeKeyAndOrderFront:nil];for(int dark=0;dark<2;dark++)for(int style=0;style<2;style++){@try{[g setValue:@(style) forKey:@"style"];}@catch(NSException*e){printf("STYLE_EXCEPTION %s\n",e.reason.UTF8String);}w.appearance=[NSAppearance appearanceNamed:dark?NSAppearanceNameDarkAqua:NSAppearanceNameAqua];[w makeKeyAndOrderFront:nil];pump(2);printf("BEGIN_MODE %s_%s WINDOW key=%d main=%d scale=%g RT=%d id=%ld\n",dark?"dark":"light",style?"clear":"regular",w.isKeyWindow,w.isMainWindow,w.backingScaleFactor,NSWorkspace.sharedWorkspace.accessibilityDisplayShouldReduceTransparency,(long)w.windowNumber);key(g,@"style");key(g,@"cornerRadius");walk(r.layer,0);printf("END_MODE %s_%s\n",dark?"dark":"light",style?"clear":"regular");fflush(stdout);}return 0;}}
